//! Structured output describing assets generated by a Trunk build.

use std::collections::BTreeMap;

use serde::{Deserialize, Serialize};

use crate::{
    pipelines::{
        Attrs,
        rust::{RustAppOutput, RustAppType},
    },
    processing::integrity::OutputDigest,
};

/// Name of the generated asset manifest in the distribution directory.
pub const ASSET_MANIFEST_FILE: &str = "trunk-assets.json";

/// Current schema version for [`AssetManifest`].
const ASSET_MANIFEST_VERSION: u32 = 1;

/// Structured references to assets emitted by one Trunk build.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct AssetManifest {
    /// Schema version; consumers must reject unsupported versions.
    pub version: u32,
    /// Public URL prefix used when emitting asset URLs.
    pub public_url: String,
    /// Finalized HTML output filename.
    pub html: String,
    /// External assets in source HTML order.
    pub assets: Vec<AssetReference>,
    /// Rust/WASM bundles. Empty for HTML-only builds.
    pub wasm: Vec<WasmBundle>,
}

/// One external asset generated from a Trunk asset element.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct AssetReference {
    /// Source element order, used to preserve CSS and script ordering.
    pub order: usize,
    /// Asset role, such as `stylesheet`, `script`, or `icon`.
    pub role: String,
    /// Exact public URL emitted by Trunk.
    pub url: String,
    /// HTML attributes emitted for this asset, excluding its URL attribute.
    pub attributes: BTreeMap<String, String>,
}

/// Runtime files and initialization configuration for one Rust application.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct WasmBundle {
    /// `main` or `worker`.
    pub app_type: String,
    /// Source element order, absent for Trunk's implicit Cargo application.
    pub order: Option<usize>,
    /// Exact URL for the wasm-bindgen JavaScript module.
    pub js_url: String,
    /// Exact URL for the generated WebAssembly module.
    pub wasm_url: String,
    /// Generated WebAssembly file size in bytes.
    pub wasm_size: u64,
    /// Exact URL for a custom initializer module, when configured.
    pub initializer_url: Option<String>,
    /// Whether the wasm-bindgen initializer expects `{ module_or_path }`.
    pub init_with_object: bool,
    /// Whether exported Rust bindings are imported into the initializer.
    pub import_bindings: bool,
    /// Global variable name used when importing Rust bindings.
    pub import_bindings_name: Option<String>,
    /// Decompression algorithm used by the generated initializer, if any.
    pub compression_algorithm: Option<String>,
    /// Cross-origin mode used when loading the bundle.
    pub cross_origin: String,
    /// Whether Trunk injects the initializer into the HTML document.
    pub inject_scripts: bool,
    /// User-configured initializer template, if any.
    pub custom_script_pattern: Option<String>,
    /// User-configured preload template, if any.
    pub custom_preload_pattern: Option<String>,
    /// Public parameters available to Trunk's custom templates.
    pub pattern_parameters: BTreeMap<String, String>,
    /// Preload resources generated by Trunk's SRI pipeline.
    pub preloads: Vec<PreloadReference>,
}

/// A preload emitted for a Rust/WASM bundle.
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub(super) struct PreloadReference {
    /// `preload` or `modulepreload`.
    pub rel: String,
    /// Exact public URL emitted by Trunk.
    pub url: String,
    /// `crossorigin` attribute value.
    pub cross_origin: String,
    /// SRI value when enabled.
    pub integrity: Option<String>,
    /// Optional preload `as` attribute.
    #[serde(rename = "as")]
    pub as_type: Option<String>,
    /// Optional preload `type` attribute.
    #[serde(rename = "type")]
    pub media_type: Option<String>,
}

impl AssetManifest {
    pub fn new(public_url: impl Into<String>, html: impl Into<String>) -> Self {
        Self {
            version: ASSET_MANIFEST_VERSION,
            public_url: public_url.into(),
            html: html.into(),
            assets: Vec::new(),
            wasm: Vec::new(),
        }
    }

    pub fn add_asset(
        &mut self,
        order: usize,
        role: impl Into<String>,
        file: &str,
        attributes: &Attrs,
        excluded_attributes: &[&str],
        integrity: Option<&OutputDigest>,
    ) {
        let mut attributes: BTreeMap<String, String> = attributes
            .iter()
            .filter(|(name, _)| {
                !name.starts_with("data-trunk") && !excluded_attributes.contains(&name.as_str())
            })
            .map(|(name, value)| (name.clone(), value.value.clone()))
            .collect();
        if let Some(integrity) = integrity.and_then(OutputDigest::to_integrity_value) {
            attributes.insert("integrity".to_owned(), integrity.to_string());
        }

        self.assets.push(AssetReference {
            order,
            role: role.into(),
            url: format!("{}{file}", self.public_url),
            attributes,
        });
    }

    pub fn add_wasm_bundle(&mut self, output: &RustAppOutput) {
        let preloads = output
            .integrities
            .entries()
            .iter()
            .map(|(key, entry)| PreloadReference {
                rel: key.r#type.to_string(),
                url: format!("{}{name}", output.cfg.public_url, name = key.name),
                cross_origin: output.cross_origin.to_string(),
                integrity: entry
                    .digest
                    .to_integrity_value()
                    .map(|integrity| integrity.to_string()),
                as_type: entry.options.r#as.clone(),
                media_type: entry.options.r#type.clone(),
            })
            .collect();

        self.wasm.push(WasmBundle {
            app_type: match output.r#type {
                RustAppType::Main => "main",
                RustAppType::Worker => "worker",
            }
            .to_owned(),
            order: output.id,
            js_url: format!("{}{file}", output.cfg.public_url, file = output.js_output),
            wasm_url: format!("{}{file}", output.cfg.public_url, file = output.wasm_output),
            wasm_size: output.wasm_size,
            initializer_url: output
                .initializer
                .as_ref()
                .map(|file| format!("{}{file}", output.cfg.public_url)),
            init_with_object: output.wasm_bindgen_features.init_with_object,
            import_bindings: output.import_bindings,
            import_bindings_name: output.import_bindings_name.clone(),
            compression_algorithm: output.compression_algorithm.clone(),
            cross_origin: output.cross_origin.to_string(),
            inject_scripts: output.cfg.inject_scripts,
            custom_script_pattern: output.cfg.pattern_script.clone(),
            custom_preload_pattern: output.cfg.pattern_preload.clone(),
            pattern_parameters: output
                .cfg
                .pattern_params
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect(),
            preloads,
        });
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::processing::integrity::IntegrityType;

    #[test]
    fn serializes_an_html_only_manifest_and_ordered_asset_metadata() {
        let mut manifest = AssetManifest::new("/app/", "index.html");
        let digest = OutputDigest::generate_from(IntegrityType::Sha384, b"style");
        let attrs = [("media".to_owned(), "screen".into())].into();
        manifest.add_asset(
            3,
            "stylesheet",
            "style-123.css",
            &attrs,
            &["href", "rel"],
            Some(&digest),
        );

        let json = serde_json::to_value(manifest).expect("serialize manifest");
        assert_eq!(json["version"], ASSET_MANIFEST_VERSION);
        assert_eq!(json["public_url"], "/app/");
        assert_eq!(json["html"], "index.html");
        assert_eq!(json["wasm"], serde_json::json!([]));
        assert_eq!(json["assets"][0]["order"], 3);
        assert_eq!(json["assets"][0]["role"], "stylesheet");
        assert_eq!(json["assets"][0]["url"], "/app/style-123.css");
        assert_eq!(json["assets"][0]["attributes"]["media"], "screen");
        assert_eq!(
            json["assets"][0]["attributes"]["integrity"],
            digest.to_integrity_value().expect("SRI digest").to_string()
        );
    }

    #[test]
    fn manifest_name_is_explicit_and_versioned() {
        assert_eq!(ASSET_MANIFEST_FILE, "trunk-assets.json");
        assert_eq!(ASSET_MANIFEST_VERSION, 1);
    }
}
